   "id": "z6faa1c75",
   "sez": "mondo",
   "titolo": "L'uragano Simon e la tempesta Rachel causano cinque morti sulle coste del Messico",
   "orig": "Hurricane Simon and Tropical Storm Rachel kill five people on Mexico’s Pacific coast",
   "lead": "Almeno cinque persone hanno perso la vita lungo la costa pacifica del Messico a causa del passaggio congiunto dell'uragano Simon e della tempesta tropicale Rachel. Le precipitazioni hanno innescato alluvioni lampo, abbattuto alberi e pali della rete elettrica, allagato numerose abitazioni e interrotto diverse vie di comunicazione. Le forze di sicurezza locali sono intervenute con l'ausilio di elicotteri per trarre in salvo decine di residenti rimasti intrappolati dalle inondazioni, mentre nello stato meridionale di Guerrero si registrano gravi danni strutturali. Lo riferisce The Guardian.",
   "more": [
    "I cicloni tropicali che colpiscono la costa pacifica messicana generano forti venti e ingenti quantità di pioggia che saturano rapidamente i corsi d'acqua montani. La combinazione di orografia impervia e deflussi improvvisi favorisce alluvioni lampo e frane, mettendo a dura prova le infrastrutture locali e i collegamenti viari."
   ],
