   "titolo": "Forte terremoto nel sud di Panama, decine di feriti e centinaia di case danneggiate",
   "orig": "Earthquake Rattles Southern Panama, Damaging Bridges and Destroying Homes",
   "lead": "Un potente sisma di magnitudo sette virgola cinque ha scosso le regioni meridionali e sud-orientali di Panama, causando almeno ventisette feriti e provocando il danneggiamento di ponti, edifici e infrastrutture vitali. Nella provincia di Chiriquí le autorità hanno segnalato danni a cinquantacinque abitazioni, diciassette delle quali dichiarate completamente inagibili, oltre a lesioni strutturali riscontrate in vari centri educativi distribuiti nei quattordici distretti monitorati. Le squadre di emergenza sono impegnate in verifiche capillari per mettere in sicurezza la popolazione e ripristinare la viabilità compromessa.",
