   "id": "z1a03385a",
   "sez": "mondo",
   "titolo": "Kim Jong Un apre un museo degli armamenti dopo un nuovo test missilistico",
   "orig": "Kim Jong Un opens new weapons museum as North Korea claims missile test success",
   "lead": "Il leader nordcoreano Kim Jong Un ha inaugurato a Pyongyang un nuovo museo degli armamenti destinato a esporre le tecnologie militari del Paese, compresi missili balistici intercontinentali con potenziale nucleare capaci di raggiungere il territorio degli Stati Uniti, insieme a droni e altre armi pesanti. Nel corso della cerimonia, annunciata dai media statali, Kim ha promesso di proseguire il potenziamento dell'arsenale. La presentazione giunge all'indomani di un test missilistico definito con successo da Pyongyang, mentre negli Stati Uniti si discutono possibili scenari diplomatici in Asia.",
   "more": [
    "L'arsenale missilistico nordcoreano comprende vettori a corto, medio e lungo raggio progettati per trasportare testate convenzionali o nucleari. Le esibizioni pubbliche di armamenti rappresentano per il regime uno strumento di propaganda interna e un segnale di deterrenza nei confronti dei rivali internazionali."
   ],
